// În risk-signal-detection.service.ts:

function detectCardiacRisks(answers: QuizAnswers): RiskSignal[] {
  const signals: RiskSignal[] = [];

  // Verifică în physicalConsiderations pentru cuvinte cheie cardiace
  if (answers.physicalConsiderations) {
    const cardiacKeywords = ['durere piept', 'palpitații', 'leșin', 'sincopă', 'cardiac'];
    if (cardiacKeywords.some(kw => answers.physicalConsiderations.toLowerCase().includes(kw))) {
      signals.push({
        specialty: 'cardiologist',
        severity: 'high',
        reason: 'Simptome cardiace detectate necesită evaluare cardiologică înainte de orice sport.',
        indicators: ['Simptome cardiace menționate'],
        absoluteContraindication: true // NOU
      });
    }
  }

  return signals;
}

// Similar pentru contuzie

// Îmbunătățește detectOrthopedistRisks:

function detectOrthopedistRisks(answers: QuizAnswers): RiskSignal[] {
  // ... cod existent ...

  // Îmbunătățire: verifică contextul
  if (answers.physicalConsiderations) {
    const considerations = answers.physicalConsiderations.toLowerCase();

    // Verifică dacă 'dureri' apare în context normal (după efort) vs patologic (persistente)
    const normalContexts = ['după efort', 'ocazional', 'după antrenament'];
    const pathologicalContexts = ['zilnic', 'persistente', 'constant', 'noaptea'];

    const hasNormalContext = normalContexts.some(ctx => considerations.includes(ctx));
    const hasPathologicalContext = pathologicalContexts.some(ctx => considerations.includes(ctx));

    if (considerations.includes('durere') || considerations.includes('dureri')) {
      if (hasPathologicalContext && !hasNormalContext) {
        // Risc ridicat - dureri patologice
        signals.push({ severity: 'high', ... });
      } else if (hasNormalContext && !hasPathologicalContext) {
        // Risc scăzut - dureri normale după efort
        signals.push({ severity: 'low', ... });
      }
    }
  }
}

