// Nou serviciu: sport-exclusion.service.ts

interface SportCategory {
  id: string;
  name: string;
  sports: string[];
}

const SPORT_CATEGORIES: SportCategory[] = [
  { id: 'contact_sports', name: 'Sporturi de contact', sports: ['fotbal', 'handbal', 'baschet', 'arte-martiale'] },
  { id: 'high_impact', name: 'Sporturi de impact ridicat', sports: ['gimnastica', 'atletism', 'volei'] },
  { id: 'low_impact', name: 'Sporturi de impact redus', sports: ['inot', 'ciclism'] },
  // etc.
];

function shouldExcludeSport(
  sportId: string,
  answers: QuizAnswers,
  riskSignals: RiskSignal[]
): { exclude: boolean; reason: string } {
  // Verifică contraindicații absolute
  const absoluteContraindications = riskSignals.filter(s => s.absoluteContraindication);

  if (absoluteContraindications.length > 0) {
    // Verifică dacă sportul este în categoriile excluse
    const sportCategory = getSportCategory(sportId);
    const excludedCategories = absoluteContraindications.flatMap(s => s.excludedSportCategories || []);

    if (excludedCategories.includes(sportCategory)) {
      return {
        exclude: true,
        reason: 'Sportul este contraindicat din cauza condițiilor medicale detectate.'
      };
    }
  }

  return { exclude: false, reason: '' };
}

